CREATE TABLE a_agg_daily_sales (sale_date DATE, ss_store_sk INT, category VARCHAR, price_band VARCHAR, tickets BIGINT, quantity BIGINT, net_paid DECIMAL(17,2), net_profit DECIMAL(17,2), d_year INT);
INSERT INTO a_agg_daily_sales (sale_date, ss_store_sk, category, price_band, tickets, quantity, net_paid, net_profit, d_year)
SELECT s.sale_date, s.ss_store_sk, i.category, i.price_band, COUNT(DISTINCT s.ss_ticket_number), SUM(s.quantity), SUM(s.net_paid), SUM(s.net_profit), s.d_year
FROM a_stg_store_sales s JOIN a_stg_item i ON i.i_item_sk = s.ss_item_sk
GROUP BY s.sale_date, s.ss_store_sk, i.category, i.price_band, s.d_year;
SELECT * FROM a_agg_daily_sales

CREATE TABLE a_agg_region_month (region STRING, d_year INT, d_moy INT, tickets BIGINT, net_paid DECIMAL(17,2));
INSERT OVERWRITE INTO a_agg_region_month
SELECT st.region, s.d_year, s.d_moy, COUNT(DISTINCT s.ss_ticket_number), SUM(s.net_paid)
FROM a_stg_store_sales s JOIN a_stg_store st ON st.s_store_sk = s.ss_store_sk
GROUP BY st.region, s.d_year, s.d_moy;
SELECT * FROM a_agg_region_month ORDER BY region NULLS FIRST, d_year NULLS FIRST, d_moy NULLS FIRST

CREATE TABLE b34_mixed (ss_item_sk INT, q BIGINT, d_year INT, d_moy INT);
DELETE FROM b34_mixed WHERE d_year = 2000 AND d_moy IN (SELECT d.d_moy FROM store_sales ss JOIN date_dim d ON d.d_date_sk = ss.ss_sold_date_sk WHERE d.d_year = 2000 AND d.d_moy = 12 AND ss_item_sk <= 30);
INSERT INTO b34_mixed (ss_item_sk, q, d_year, d_moy) SELECT ss_item_sk, SUM(ss_quantity), 2000, d.d_moy FROM store_sales ss JOIN date_dim d ON d.d_date_sk = ss.ss_sold_date_sk WHERE d.d_year = 2000 AND d.d_moy = 12 AND ss_item_sk <= 30 GROUP BY ss_item_sk, d.d_moy;
