INSERT INTO b34_mixed (ss_item_sk, q, d_year, d_moy) SELECT ss_item_sk, SUM(ss_quantity), 2001, d.d_moy FROM store_sales ss JOIN date_dim d ON d.d_date_sk = ss.ss_sold_date_sk WHERE d.d_year = 2001 AND d.d_moy = 2 AND ss_item_sk <= 30 GROUP BY ss_item_sk, d.d_moy;
