CREATE TABLE b68_daily (ss_store_sk INT, paid DECIMAL(17,2), load_ts TIMESTAMP_NTZ);
INSERT OVERWRITE INTO b68_daily SELECT ss_store_sk, SUM(ss_net_paid), CURRENT_TIMESTAMP()::TIMESTAMP_NTZ FROM store_sales WHERE ss_sold_date_sk BETWEEN 2451545 AND 2451560 GROUP BY ss_store_sk;
SELECT * FROM b68_daily ORDER BY ss_store_sk

CREATE TABLE a_agg_category_year (d_year INT, category STRING, net_paid DECIMAL(17,2), net_profit DECIMAL(17,2), tickets BIGINT);
INSERT OVERWRITE INTO a_agg_category_year SELECT d_year, category, SUM(net_paid), SUM(net_profit), SUM(tickets) FROM a_agg_daily_sales GROUP BY d_year, category;
SELECT * FROM a_agg_category_year ORDER BY d_year, category
